async function registerProject(page: Page, prefix: string) {
  const name = `${prefix} ${randomUUID().slice(0, 8)}`;
  await page.goto("/projects/new");
  await page.getByLabel("Nom du projet", { exact: true }).fill(name);
  await page.getByRole("button", { name: "Enregistrer le projet", exact: true }).click();
  await expect(page.getByRole("heading", { name, exact: true })).toBeVisible();
  return name;
}

async function openRecovery(page: Page) {
  await page.goto("/databases");
  await expect(
    page.getByRole("heading", { name: "Sauvegardes et restauration isolée", exact: true }),
  ).toBeVisible();
  return {
    backup: page.getByRole("form", { name: "Préparer une sauvegarde physique", exact: true }),
    restore: page.getByRole("form", { name: "Préparer une restauration isolée", exact: true }),
  };
}

async function recoveryRequest(page: Page, path: string, body?: unknown) {
  return page.evaluate(
    async ({ url, body, versionHeader, version }) => {
      const response = await fetch(url, {
        method: body === undefined ? "GET" : "POST",
        headers: {
          "content-type": "application/json",
          [versionHeader]: version,
          ...(body === undefined ? {} : { "idempotency-key": crypto.randomUUID() }),
        },
        ...(body === undefined ? {} : { body: JSON.stringify(body) }),
      });
      return { status: response.status, text: await response.text() };
    },
    {
      url: `${LOCAL_DEFAULTS.apiBase}/recovery${path}`,
      body,
      versionHeader: CONTROL_API_HEADER,
      version: CONTROL_API_VERSION,
    },
  );
}

// This is the ordinary product configuration: no qualified physical provider or fabricated source.
test("T-AC-35 T-AC-39 T-AC-42 exposes bounded preparations and rejects private execution inputs without claiming readiness", async ({
  page,
}) => {
  const { backup, restore } = await openRecovery(page);
  await expect(
    page.getByRole("heading", { name: "Exécution de sauvegarde à qualifier", exact: true }),
  ).toBeVisible();
  await expect(page.getByText(/Aucun ordonnanceur automatique qualifié/)).toBeVisible();
  await expect(
    page.getByText(/Activation bloquée : fichiers, authentification, configuration/),
  ).toBeVisible();
  await expect(
    backup.getByRole("combobox", { name: "Base source vérifiée", exact: true }).locator("option"),
  ).toHaveCount(1);
  await expect(
    backup.getByRole("button", { name: "Préparer la sauvegarde", exact: true }),
  ).toBeDisabled();
  await expect(
    restore.getByRole("button", { name: "Préparer la restauration isolée", exact: true }),
  ).toBeDisabled();
  const retention = backup.getByLabel("Générations complètes conservées", { exact: true });
  await expect(retention).toHaveAttribute("min", "2");
  await expect(retention).toHaveAttribute("max", "4");
  await retention.fill("1");
  expect(await retention.evaluate((input: HTMLInputElement) => input.validity.rangeUnderflow)).toBe(
    true,
  );
  const before = await recoveryRequest(page, "");
  expect(before.status).toBe(200);
  expect(RecoveryOverview.parse(JSON.parse(before.text))).toMatchObject({
    execution: "unconfigured",
    activation: "blocked",
    schedule: "prepared-only",
    preparations: [],
    backups: [],
    runs: [],
  });
  const marker = `private-path-${randomUUID()}`;
  const rejected = await recoveryRequest(page, "/backups/preparations", {
    projectId: randomUUID(),
    environmentId: randomUUID(),
    sourceAllocationId: randomUUID(),
    expectedProjectRevision: 0,
    expectedEnvironmentRevision: 0,
    kind: "full",
    policy: {
      fullRetention: 2,
      differentialRetention: 7,
      repositoryGiB: 8,
      stagingGiB: 2,
      archiveHeadroomGiB: 1,
      maxArchiveAgeSeconds: 300,
    },
    path: marker,
  });
  expect(rejected.status).toBe(422);
  expect(rejected.text).not.toContain(marker);
  expect(await recoveryRequest(page, "")).toEqual(before);
  await page.reload();
  await expect(
    backup.getByRole("button", { name: "Préparer la sauvegarde", exact: true }),
  ).toBeDisabled();
  await page.screenshot({ path: "artifacts/recovery-desktop.png", fullPage: true });
});

// Cross project changes and persisted database preparations must never manufacture a READY source.
test("T-AC-35 T-AC-38 T-AC-42 excludes planned profiles across project changes and reload", async ({
  page,
}) => {
  const first = await registerProject(page, "Recovery source e2e");
  const second = await registerProject(page, "Recovery foreign e2e");
  const { backup, restore } = await openRecovery(page);
  const profile = page.getByRole("form", { name: "Préparer une base indépendante", exact: true });
  for (const name of [first, second, first]) {
    await profile
      .getByRole("combobox", { name: "Projet", exact: true })
      .selectOption({ label: name });
    await profile
      .getByRole("combobox", { name: "Environnement", exact: true })
      .selectOption({ label: "Développement" });
    await expect(
      backup.getByRole("combobox", { name: "Base source vérifiée", exact: true }),
    ).toHaveValue("");
  }
  const prepared = page.waitForResponse(
    (response) =>
      new URL(response.url()).pathname.endsWith("/databases/preparations") &&
      response.request().method() === "POST",
  );
  await profile.getByRole("button", { name: "Préparer le profil PostgreSQL", exact: true }).click();
  expect((await prepared).status()).toBe(201);
  const card = page.getByRole("region", { name: `Profil ${first} development`, exact: true });
  await expect(card).toBeVisible();
  await expect(card.getByText("Prévu", { exact: true })).toBeVisible();
  await expect(
    backup.getByRole("combobox", { name: "Base source vérifiée", exact: true }).locator("option"),
  ).toHaveCount(1);
  await page.reload();
  await expect(card).toBeVisible();
  await expect(backup.getByText(/Aucune base source vérifiée/)).toBeVisible();
  await expect(restore.getByText(/Aucune sauvegarde avec intervalle/)).toBeVisible();
  await expect(
    backup.getByRole("button", { name: "Préparer la sauvegarde", exact: true }),
  ).toBeDisabled();
  await expect(
    restore.getByRole("button", { name: "Préparer la restauration isolée", exact: true }),
  ).toBeDisabled();
});

